```json
{
  "root_causes": [
    {
      "service": "product-catalog",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' AS period, count(*) AS product_catalog_spans FROM normal_traces WHERE service_name = 'product-catalog' UNION ALL SELECT 'abnormal', count(*) FROM abnormal_traces WHERE service_name = 'product-catalog'",
          "claim": "product-catalog emitted about 178 spans in the normal window and zero spans in the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errors, round(avg(duration)/1e6,2) AS avg_ms FROM abnormal_traces WHERE span_name LIKE '%ProductCatalogService/GetProduct%' OR span_name LIKE '%ProductCatalogService/ListProducts%' GROUP BY ALL ORDER BY 1,2",
          "claim": "Every abnormal GetProduct/ListProducts call from frontend, checkout and recommendation errors within about 0.1-0.4 ms, with no successful product-catalog responses."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n, round(avg(duration)/1e6,2) AS avg_ms FROM abnormal_traces WHERE service_name = 'frontend' AND span_name IN ('tcp.connect','dns.lookup') GROUP BY ALL ORDER BY 1,2",
          "claim": "Frontend tcp.connect spans fail on every attempt while dns.lookup succeeds, so the connection to product-catalog is refused."
        },
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name AS pod, metric, value FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'product-catalog%' AND metric IN ('k8s.container.restarts','container.memory.usage') ORDER BY time LIMIT 40",
          "claim": "product-catalog container restart counter rose from 0 to 1 at the window boundary and its container metrics only resume at 11:39 with a fresh memory footprint."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, count(*) AS n FROM abnormal_logs WHERE service_name = 'product-catalog' GROUP BY 1",
          "claim": "product-catalog wrote no logs in the abnormal window, against 179 INFO logs in the normal window."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "product-catalog",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errors FROM abnormal_traces WHERE service_name = 'checkout' AND (span_name LIKE '%ProductCatalog%' OR span_name LIKE '%PlaceOrder%') GROUP BY ALL",
          "claim": "All checkout GetProduct client calls and all PlaceOrder server spans fail in the abnormal window."
        }
      ]
    },
    {
      "from": "product-catalog",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errors FROM abnormal_traces WHERE service_name = 'frontend' AND span_name LIKE '%ProductCatalogService/GetProduct%' GROUP BY 1",
          "claim": "All frontend gRPc GetProduct client calls to product-catalog error in the abnormal window, with a 0% success rate."
        }
      ]
    },
    {
      "from": "product-catalog",
      "to": "recommendation",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errors FROM abnormal_traces WHERE service_name = 'recommendation' GROUP BY ALL",
          "claim": "Every recommendation ListProducts client call to product-catalog errors in the abnormal window."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errors FROM abnormal_traces WHERE span_name LIKE '%CheckoutService/PlaceOrder%' GROUP BY ALL",
          "claim": "PlaceOrder fails in checkout and the frontend's client calls to it both return errors in the abnormal window."
        }
      ]
    },
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errors FROM abnormal_traces WHERE span_name LIKE '%ListRecommendations%' GROUP BY ALL",
          "claim": "Frontend ListRecommendations calls all error in the abnormal window, following the recommendation service's failed product-catalog calls."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errors, sum(CASE WHEN attr_http_response_status_code >= 500 THEN 1 ELSE 0 END) AS http_5xx FROM abnormal_traces WHERE service_name = 'frontend-proxy' AND span_name = 'ingress' GROUP BY ALL",
          "claim": "Frontend-proxy ingress returns about 137 errors out of 222 requests in the abnormal window, against 36 out of 514 in the normal window."
        }
      ]
    }
  ]
}
